#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){
  int n,m; scanf("%d %d",&n,&m);
  ll x,y; int k; scanf("%lld %d %lld",&x,&k,&y);
  vector<int>a(n); for(auto&v:a) scanf("%d",&v);
  vector<int>b(m); for(auto&v:b) scanf("%d",&v);
  vector<int> pos(n+1,-1);
  for(int i=0;i<n;i++) pos[a[i]]=i;
  vector<int> kept; int last=-1;
  for(int v:b){ int p=pos[v]; if(p<0||p<=last){puts("-1");return 0;} kept.push_back(p); last=p; }
  kept.push_back(n);
  ll total=0; int prev=-1;
  for(int p:kept){
    int L=p-prev-1;
    if(L>0){
      int lv=prev>=0?a[prev]:0, rv=p<n?a[p]:0;
      int segMax=0; for(int i=prev+1;i<p;i++) segMax=max(segMax,a[i]);
      bool need = segMax>max(lv,rv);
      ll best=LLONG_MAX;
      for(ll f=need?1:0; f*k<=L; f++){
        ll c=f*x+(ll)(L-f*k)*y;
        best=min(best,c);
      }
      if(best==LLONG_MAX){puts("-1");return 0;}
      total+=best;
    }
    prev=p;
  }
  printf("%lld\n",total);
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){
  int n; scanf("%d",&n);
  vector<ll> a(n); vector<int> b(n);
  for(auto&v:a) scanf("%lld",&v);
  for(auto&v:b){ scanf("%d",&v); v = v>0 ? v-1 : -1; }
  vector<vector<int>> ch(n);
  vector<int> indeg(n,0);
  for(int i=0;i<n;i++) if(b[i]>=0){ ch[b[i]].push_back(i); indeg[b[i]]++; }
  vector<ll> cur=a; ll ans=0;
  vector<int> q;
  for(int i=0;i<n;i++) if(indeg[i]==0) q.push_back(i);
  for(size_t h=0;h<q.size();h++){
    int v=q[h];
    ans+=cur[v];
    if(b[v]>=0){
      if(cur[v]>=0) cur[b[v]]+=cur[v];
      if(--indeg[b[v]]==0) q.push_back(b[v]);
    }
  }
  vector<int> order; vector<pair<int,int>> st; // (type 0 expand / 1 emit, node)
  for(int r=0;r<n;r++) if(b[r]<0) st.push_back({0,r});
  while(!st.empty()){
    auto [type,v]=st.back(); st.pop_back();
    if(type==1){ order.push_back(v); continue; }
    for(int c:ch[v]) if(cur[c]<0) st.push_back({0,c});
    st.push_back({1,v});
    for(int c:ch[v]) if(cur[c]>=0) st.push_back({0,c});
  }
  printf("%lld\n",ans);
  for(size_t i=0;i<order.size();i++) printf("%d%c",order[i]+1,i+1<order.size()?' ':'\n');
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){
  int t; scanf("%d",&t);
  while(t--){
    int n; ll S; scanf("%d %lld",&n,&S);
    vector<vector<pair<int,int>>> g(n+1);
    for(int i=0;i<n-1;i++){int v,u,w; scanf("%d %d %d",&v,&u,&w); g[v].push_back({u,w}); g[u].push_back({v,w});}
    vector<int> par(n+1,0), order{1}, w(n+1,0);
    vector<ll> leaves(n+1,0);
    par[1]=-1;
    for(size_t h=0;h<order.size();h++){
      int v=order[h];
      for(auto [u,ww]:g[v]) if(u!=par[v]){ par[u]=v; w[u]=ww; order.push_back(u); }
    }
    for(int i=(int)order.size()-1;i>=0;i--){
      int v=order[i];
      if(v!=1 && g[v].size()==1) leaves[v]=1;
      if(v!=1) leaves[par[v]]+=leaves[v];
    }
    ll sum=0; priority_queue<pair<ll,int>> pq;
    for(int v=2;v<=n;v++){ sum+=(ll)w[v]*leaves[v]; pq.push({(ll)(w[v]-w[v]/2)*leaves[v],v}); }
    int ops=0;
    while(sum>S){
      auto [gain,v]=pq.top(); pq.pop();
      sum-=gain; w[v]/=2; ops++;
      pq.push({(ll)(w[v]-w[v]/2)*leaves[v],v});
    }
    printf("%d\n",ops);
  }
}

