    for(int i=1;i<=n;i++){ scanf("%lld",&a[i]); s+=a[i]; }
    if(s%n){ puts("-1"); continue; }
    ll avg=s/n;
    vector<array<ll,3>> ops;
    auto op=[&](int src,int dst,ll x){
      if(x<=0) return;
      a[src]-=x*src; a[dst]+=x*src; ops.push_back({src,dst,x});
    };
    for(int i=2;i<=n;i++){
      ll r=a[i]%i;
      if(r) op(1,i,i-r);
      op(i,1,a[i]/i);
    }
    for(int i=2;i<=n;i++) op(1,i,avg);
    printf("%d\n",(int)ops.size());
    for(auto&o:ops) printf("%lld %lld %lld\n",o[0],o[1],o[2]);
  }
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){
  int n[4]; for(int i=0;i<4;i++) scanf("%d",&n[i]);
  vector<ll> c[4];
  for(int i=0;i<4;i++){ c[i].resize(n[i]); for(auto&v:c[i]) scanf("%lld",&v); }
  unordered_set<ll> ban[3];
  auto key=[](ll x,ll y){ return x*300007LL+y; };
  for(int L=0;L<3;L++){ int m; scanf("%d",&m); while(m--){ int x,y; scanf("%d %d",&x,&y); ban[L].insert(key(x-1,y-1)); } }
  vector<int> o[4];
  for(int i=0;i<4;i++){
    o[i].resize(n[i]); iota(o[i].begin(),o[i].end(),0);
    sort(o[i].begin(),o[i].end(),[&](int a,int b){ return c[i][a]<c[i][b]; });
  }
  const ll INF=LLONG_MAX;
  vector<ll> A(n[1],INF), B(n[2],INF);
  for(int s=0;s<n[1];s++) for(int f:o[0]) if(!ban[0].count(key(f,s))){ A[s]=c[0][f]+c[1][s]; break; }
  for(int d=0;d<n[2];d++) for(int e:o[3]) if(!ban[2].count(key(d,e))){ B[d]=c[2][d]+c[3][e]; break; }
  vector<int> sa(n[1]), sb(n[2]);
  iota(sa.begin(),sa.end(),0); iota(sb.begin(),sb.end(),0);
  sort(sa.begin(),sa.end(),[&](int a,int b){ return A[a]<A[b]; });
  sort(sb.begin(),sb.end(),[&](int a,int b){ return B[a]<B[b]; });
  ll ans=INF;
  for(int s:sa){
    if(A[s]==INF) break;
    for(int d:sb){
      if(B[d]==INF) break;
      if(!ban[1].count(key(s,d))){ ans=min(ans,A[s]+B[d]); break; }
    }
  }
  printf("%lld\n", ans==INF ? -1LL : ans);
}

#include <bits/stdc++.h>
using namespace std;
static char buf[100005];
int main(){
  int T; scanf("%d",&T);
  while(T--){
    int n,k; scanf("%d %d",&n,&k);
    scanf("%s",buf); string s(buf);
    if(n%k){ puts("-1"); continue; }
    int cnt[26]={0};
    for(char ch:s) cnt[ch-'a']++;
    auto needTotal=[&](int *c){ int r=0; for(int x=0;x<26;x++) r+=(k-c[x]%k)%k; return r; };
    if(needTotal(cnt)==0){ printf("%s\n",s.c_str()); continue; }
    bool found=false;
    for(int i=n-1;i>=0 && !found;i--){
      cnt[s[i]-'a']--;
      for(int c=s[i]-'a'+1;c<26 && !found;c++){
        cnt[c]++;
        int R=n-i-1; int nd=needTotal(cnt);
        if(nd<=R){
          string res=s.substr(0,i); res.push_back('a'+c);
          int add[26];
          for(int x=0;x<26;x++) add[x]=(k-cnt[x]%k)%k;
          add[0]+=R-nd;
          for(int x=0;x<26;x++) res.append(add[x],'a'+x);
          printf("%s\n",res.c_str()); found=true;
        } else cnt[c]--;
      }
    }
    if(!found) puts("-1");
  }
}

#include <bits/stdc++.h>
using namespace std;
typedef pair<int,int> P;
P mergeP(P x,P y){
  if(x.first==y.first) return {x.first,x.second+y.second};
  if(x.second>=y.second) return {x.first,x.second-y.second};
  return {y.first,y.second-x.second};
}
int main(){
  int n,q; scanf("%d %d",&n,&q);
  vector<int> a(n);
  for(auto&v:a) scanf("%d",&v);
  int sz=1; while(sz<n) sz<<=1;
  vector<P> seg(2*sz,{0,0});
  for(int i=0;i<n;i++) seg[sz+i]={a[i],1};
  for(int i=sz-1;i>=1;i--) seg[i]=mergeP(seg[2*i],seg[2*i+1]);
  vector<vector<int>> pos(n+1);
  for(int i=0;i<n;i++) pos[a[i]].push_back(i);
  while(q--){
    int l,r; scanf("%d %d",&l,&r); l--; r--;
    P res={0,0};
    for(int lo=l+sz,hi=r+sz+1; lo<hi; lo>>=1,hi>>=1){
      if(lo&1) res=mergeP(res,seg[lo++]);
      if(hi&1) res=mergeP(res,seg[--hi]);
    }
    int c=res.first, f=0;
    if(c>0) f=upper_bound(pos[c].begin(),pos[c].end(),r)-lower_bound(pos[c].begin(),pos[c].end(),l);
    int len=r-l+1;
    printf("%d\n",max(1,2*f-len));
  }
}

