#include <bits/stdc++.h>
using namespace std;
int main(){
  int n; scanf("%d",&n);
  map<int,vector<int>> g;
  for(int i=0;i<n;i++){ int m,k; scanf("%d %d",&m,&k); g[m].push_back(k); }
  vector<int> keys; vector<vector<int>> ks;
  for(auto&[m,v]:g){ keys.push_back(m); ks.push_back(v); }
  int G=keys.size();
  double bestVal=-1; vector<int> bestSet; int bestT=0;
  for(int t=1;t<=min(G,20);t++){
    vector<pair<double,int>> w(G);
    for(int g2=0;g2<G;g2++){ double s=0; for(int k:ks[g2]) s+=min(1.0,(double)k/t); w[g2]={s,g2}; }
    sort(w.rbegin(),w.rend());
    double val=0; for(int j=0;j<t;j++) val+=w[j].first;
    if(val>bestVal+1e-12){ bestVal=val; bestT=t; bestSet.clear(); for(int j=0;j<t;j++) bestSet.push_back(w[j].second); }
  }
  vector<pair<long long,int>> K(G);
  for(int g2=0;g2<G;g2++){ long long s=0; for(int k:ks[g2]) s+=k; K[g2]={s,g2}; }
  sort(K.rbegin(),K.rend());
  long long pre=0;
  for(int t=1;t<=G;t++){
    pre+=K[t-1].first;
    if(t>20){
      double val=(double)pre/t;
      if(val>bestVal+1e-12){ bestVal=val; bestT=t; bestSet.clear(); for(int j=0;j<t;j++) bestSet.push_back(K[j].second); }
    }
  }
  printf("%d\n",bestT);
  for(size_t j=0;j<bestSet.size();j++) printf("%d%c",keys[bestSet[j]],j+1<bestSet.size()?' ':'\n');
}

