#include <bits/stdc++.h>
using namespace std;
int par_[200005];
int findp(int x){ while(par_[x]!=x){ par_[x]=par_[par_[x]]; x=par_[x]; } return x; }
int main(){
  int T; scanf("%d",&T);
  while(T--){
    int n; long long k; scanf("%d %lld",&n,&k);
    vector<long long> x(n),y(n),tm(n);
    for(int i=0;i<n;i++){ scanf("%lld %lld %lld",&x[i],&y[i],&tm[i]); par_[i]=i; }
    auto uni=[&](int a,int b){ a=findp(a); b=findp(b); if(a!=b) par_[a]=b; };
    vector<int> id(n); iota(id.begin(),id.end(),0);
    sort(id.begin(),id.end(),[&](int a,int b){ return make_pair(x[a],y[a])<make_pair(x[b],y[b]); });
    for(int i=0;i+1<n;i++){ int a=id[i],b=id[i+1]; if(x[a]==x[b]&&y[b]-y[a]<=k) uni(a,b); }
    sort(id.begin(),id.end(),[&](int a,int b){ return make_pair(y[a],x[a])<make_pair(y[b],x[b]); });
    for(int i=0;i+1<n;i++){ int a=id[i],b=id[i+1]; if(y[a]==y[b]&&x[b]-x[a]<=k) uni(a,b); }
    vector<long long> mn(n,LLONG_MAX);
    for(int i=0;i<n;i++){ int r=findp(i); mn[r]=min(mn[r],tm[i]); }
    vector<long long> M;
    for(int i=0;i<n;i++) if(findp(i)==i) M.push_back(mn[i]);
    sort(M.begin(),M.end());
    long long lo=0, hi=M.back();
    auto ok=[&](long long Tt){ long long cnt=M.end()-upper_bound(M.begin(),M.end(),Tt); return cnt<=Tt+1; };
    while(lo<hi){ long long mid=(lo+hi)/2; if(ok(mid)) hi=mid; else lo=mid+1; }
    printf("%lld\n",lo);
  }
}

