#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
ll cdiv(ll p,ll q){ return p<=0?0:(p+q-1)/q; }
int main(){
  int n; scanf("%d",&n);
  vector<ll> a(n); for(auto&v:a) scanf("%lld",&v);
  ll ans=LLONG_MAX;
  for(int i=0;i+1<n;i++){
    ll A=a[i],B=a[i+1]; ll ys=(2*B-A)/3;
    vector<ll> cand={0,(B+1)/2,ys-3,ys-2,ys-1,ys,ys+1,ys+2,ys+3};
    for(ll y:cand){ if(y<0) continue; ll x=max(cdiv(A-y,2),max(0LL,B-2*y)); ans=min(ans,x+y); }
  }
  for(int i=0;i+2<n;i++){
    ll A=a[i],B=a[i+2]; ll mn=min(A,B);
    for(ll t: {0LL,1LL,mn-1,mn}){ if(t<0) continue; ans=min(ans,t+cdiv(A-t,2)+cdiv(B-t,2)); }
  }
  vector<ll> c(n); for(int i=0;i<n;i++) c[i]=(a[i]+1)/2;
  vector<ll> pre(n),suf(n);
  for(int i=0;i<n;i++) pre[i]=min(i?pre[i-1]:LLONG_MAX,c[i]);
  for(int i=n-1;i>=0;i--) suf[i]=min(i+1<n?suf[i+1]:LLONG_MAX,c[i]);
  for(int i=0;i<n;i++){
    if(i-3>=0) ans=min(ans,c[i]+pre[i-3]);
    if(i+3<n) ans=min(ans,c[i]+suf[i+3]);
  }
  printf("%lld\n",ans);
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll INF=LLONG_MAX;
vector<ll> a,mn,cR;
ll f(int nd,int l,int r,ll v){
  if(mn[nd]>=v) return 0;
  if(l==r) return 1;
  int m=(l+r)/2;
  if(mn[2*nd]<v) return f(2*nd,l,m,v)+cR[nd];
  return f(2*nd+1,m+1,r,v);
}
void pull(int nd,int l,int r){
  int m=(l+r)/2; mn[nd]=min(mn[2*nd],mn[2*nd+1]); cR[nd]=f(2*nd+1,m+1,r,mn[2*nd]);
}
void build(int nd,int l,int r){
  if(l==r){ mn[nd]=a[l]; return; }
  int m=(l+r)/2; build(2*nd,l,m); build(2*nd+1,m+1,r); pull(nd,l,r);
}
void upd(int nd,int l,int r,int p,ll val){
  if(l==r){ mn[nd]=val; return; }
  int m=(l+r)/2; if(p<=m) upd(2*nd,l,m,p,val); else upd(2*nd+1,m+1,r,p,val); pull(nd,l,r);
}
int main(){
  int t; scanf("%d",&t);
  while(t--){
