#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){
  int t; scanf("%d",&t);
  vector<ll> f={1,1};
  while(f.size()<80) f.push_back(f[f.size()-1]+f[f.size()-2]);
  while(t--){
    int k; scanf("%d",&k);
    vector<ll> c(k); ll tot=0;
    for(auto&v:c){ scanf("%lld",&v); tot+=v; }
    int K=-1; ll ps=0;
    for(int i=0;i<(int)f.size();i++){ ps+=f[i]; if(ps==tot){ K=i+1; break; } if(ps>tot) break; }
    if(K<0){ puts("NO"); continue; }
    int prev=-1; bool ok=true;
    for(int i=K-1;i>=0&&ok;i--){
      int best=-1;
      for(int j=0;j<k;j++) if(j!=prev&&(best<0||c[j]>c[best])) best=j;
      if(best<0||c[best]<f[i]){ ok=false; break; }
      c[best]-=f[i]; prev=best;
    }
    puts(ok?"YES":"NO");
  }
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
struct TopK{
  int k; multiset<ll> top,rest; ll sum=0;
  TopK(int kk):k(kk){}
  void ins(ll x){ top.insert(x); sum+=x; if((int)top.size()>k){ auto it=top.begin(); sum-=*it; rest.insert(*it); top.erase(it); } }
  void era(ll x){
    auto it=top.find(x);
    if(it!=top.end()){
      top.erase(it); sum-=x;
      if(!rest.empty()){ auto r=prev(rest.end()); sum+=*r; top.insert(*r); rest.erase(r); }
    } else rest.erase(rest.find(x));
  }
};
int main(){
  int n,len; scanf("%d %d",&n,&len);
  vector<ll> a(n); for(auto&v:a) scanf("%lld",&v);
  int k; scanf("%d",&k);
  TopK NEG(k),POS(k);
  ll S=0, best=0;
  auto addv=[&](int i,int sg){
    ll x=a[i]; S+=sg*x;
    if(x<0){ if(sg>0) NEG.ins(-x); else NEG.era(-x); }
    else if(x>0){ if(sg>0) POS.ins(x); else POS.era(x); }
  };
  for(int i=0;i<n;i++){
    addv(i,+1);
    if(i>=len) addv(i-len,-1);
    if(i>=len-1) best=max(best,max(S+2*NEG.sum,-(S-2*POS.sum)));
  }
  printf("%lld\n",best);
}
